import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv2d kernel using CuTe tensors for indexing.
// Each block handles OcPerBlock output channels and PTile output spatial
// positions for a single batch element. Weights for the OcPerBlock
// channels (across all C_in and kernel positions) are staged in shared
// memory once per block (they fit comfortably since C_in and kernel are
// small for this problem), then reused for every output pixel handled
// by the block.
template <typename T, int OH_TILE, int OW_TILE, int OcPerBlock>
__global__ void conv2d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride, int padding,
    int Hout, int Wout,
    int num_oh_tiles)
{
  constexpr int Threads = OH_TILE * OW_TILE;
  const int tid = threadIdx.x;
  const int local_oh = tid / OW_TILE;
  const int local_ow = tid % OW_TILE;
  const int n       = blockIdx.z;
  const int oh_tile = blockIdx.y % num_oh_tiles;
  const int oc_tile = blockIdx.y / num_oh_tiles;
  const int ow_tile = blockIdx.x;
  const int oc_base = oc_tile * OcPerBlock;
  const int oh_base = oh_tile * OH_TILE;
  const int ow_base = ow_tile * OW_TILE;
  const int oh = oh_base + local_oh;
  const int ow = ow_base + local_ow;
  const int KTotal = Cin * Kh * Kw;
  const int IH_TILE = (OH_TILE - 1) * stride + Kh;
  const int IW_TILE = (OW_TILE - 1) * stride + Kw;
  // Strides for contiguous NCHW layout
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{}));
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{}));
  // Weight flattened as (Cout, Cin*Kh*Kw), contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, KTotal),
      make_stride(KTotal, Int<1>{}));
  // Shared memory: weights for OcPerBlock channels x all K positions,
  // followed by cooperative input tile staging (Cin x IH_TILE x IW_TILE)
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr = sW_ptr + (size_t)OcPerBlock * (size_t)KTotal;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, KTotal),
      make_stride(KTotal, Int<1>{}));
  // Load weight chunk for this block's output channels
  for (int kk = tid; kk < KTotal; kk += Threads) {
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
      int oc = oc_base + cc;
      T wval = T(0);
      if (oc < Cout) {
        wval = mW(oc, kk);
      }
      sW(cc, kk) = wval;
    }
  }
  // Cooperatively stage the input patch needed by this whole block into
  // shared memory once, so every output pixel/channel in the block reuses
  // it instead of re-reading overlapping input from global memory.
  const int tile_hw    = IH_TILE * IW_TILE;
  const int tile_elems = Cin * tile_hw;
  for (int idx = tid; idx < tile_elems; idx += Threads) {
    int ic  = idx / tile_hw;
    int rem = idx - ic * tile_hw;
    int ti  = rem / IW_TILE;
    int tj  = rem - ti * IW_TILE;
    int ih = oh_base * stride - padding + ti;
    int iw = ow_base * stride - padding + tj;
    T xval = T(0);
    if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
      xval = mX(ic, ih, iw);
    }
    sX_ptr[idx] = xval;
  }
  __syncthreads();
  const bool valid = (oh < Hout) && (ow < Wout);
  // Accumulators, initialized with bias if present
  float acc[OcPerBlock];
  #pragma unroll
  for (int cc = 0; cc < OcPerBlock; ++cc) {
    int oc = oc_base + cc;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    acc[cc] = bval;
  }
  if (valid) {
    const int base_ti = local_oh * stride;
    const int base_tj = local_ow * stride;
    for (int ic = 0; ic < Cin; ++ic) {
      const T* sX_ic = sX_ptr + (size_t)ic * tile_hw;
      for (int kh = 0; kh < Kh; ++kh) {
        const T* row = sX_ic + (base_ti + kh) * IW_TILE + base_tj;
        const int k_row = (ic * Kh + kh) * Kw;
        for (int kw = 0; kw < Kw; ++kw) {
          float xval = (float)row[kw];
          int k = k_row + kw;
          #pragma unroll
          for (int cc = 0; cc < OcPerBlock; ++cc) {
            acc[cc] += xval * (float)sW(cc, k);
          }
        }
      }
    }
  }
  // Store results
  if (valid) {
    #pragma unroll
    for (int cc = 0; cc < OcPerBlock; ++cc) {
      int oc = oc_base + cc;
      if (oc < Cout) {
        mY(oc, oh, ow) = static_cast<T>(acc[cc]);
      }
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 assumed)");
  int64_t Kh   = w.size(2);
  int64_t Kw   = w.size(3);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - Kh) / stride + 1;
  int64_t Wout = (Win + 2 * padding - Kw) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int OH_TILE    = 8;
  constexpr int OW_TILE    = 16;
  constexpr int OcPerBlock = 4;
  constexpr int Threads    = OH_TILE * OW_TILE;
  const int num_ow_tiles = (int)((Wout + OW_TILE - 1) / OW_TILE);
  const int num_oh_tiles = (int)((Hout + OH_TILE - 1) / OH_TILE);
  const int num_oc_tiles = (int)((Cout + OcPerBlock - 1) / OcPerBlock);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)num_ow_tiles,
      (unsigned)(num_oh_tiles * num_oc_tiles),
      (unsigned)N
  );
  int KTotal = (int)(Cin * Kh * Kw);
  int IH_TILE = (OH_TILE - 1) * stride + (int)Kh;
  int IW_TILE = (OW_TILE - 1) * stride + (int)Kw;
  size_t smem_bytes = (size_t)OcPerBlock * (size_t)KTotal * sizeof(float)
                     + (size_t)Cin * (size_t)IH_TILE * (size_t)IW_TILE * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  cudaFuncSetAttribute(
      conv2d_cute_kernel<float, OH_TILE, OW_TILE, OcPerBlock>,
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      (int)smem_bytes);
  conv2d_cute_kernel<float, OH_TILE, OW_TILE, OcPerBlock><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      (int)stride, (int)padding,
      (int)Hout, (int)Wout,
      num_oh_tiles
  );
  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_alexnet_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size, kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)
        self._ext = conv2d_ext

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

